Definition ceiling_of_sp (sp : Z) : Ceiling :=
  mkCeiling (ceiling_raw sp) (ceiling_raw_ge sp) (ceiling_raw_le sp) (ceiling_raw_al sp).

Lemma ceiling_of_sp_eq : forall sp,
  0x7fff80000000 <= sp <= 0x800000000000 -> sp mod 16 = 0 ->
